<?php
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();$id=(int)($_POST['id']??0);$d=[trim($_POST['name']),trim($_POST['document']),trim($_POST['phone']),trim($_POST['email']),trim($_POST['address'])];if($id){$pdo->prepare('UPDATE customers SET name=?,document=?,phone=?,email=?,address=? WHERE id=?')->execute([...$d,$id]);}else{$pdo->prepare('INSERT INTO customers(name,document,phone,email,address) VALUES(?,?,?,?,?)')->execute($d);}flash('success','Cliente salvo.');redirect('index.php?page=customers');}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM customers WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}
$q=trim($_GET['q']??'');$st=$pdo->prepare('SELECT * FROM customers WHERE name LIKE ? OR document LIKE ? OR phone LIKE ? ORDER BY id DESC');$st->execute(["%$q%","%$q%","%$q%"]);$rows=$st->fetchAll();$title='Clientes';require __DIR__.'/../../includes/header.php';?>
<div class="page-head"><div><h1>Clientes</h1><p>Cadastro para histórico e identificação das vendas.</p></div></div><div class="grid two"><section class="panel"><h2><?=$edit?'Editar cliente':'Novo cliente'?></h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><label class="span2">Nome<input name="name" required value="<?=e($edit['name']??'')?>"></label><label>CPF/CNPJ<input name="document" value="<?=e($edit['document']??'')?>"></label><label>Telefone<input name="phone" value="<?=e($edit['phone']??'')?>"></label><label class="span2">E-mail<input type="email" name="email" value="<?=e($edit['email']??'')?>"></label><label class="span2">Endereço<textarea name="address"><?=e($edit['address']??'')?></textarea></label><div class="span2"><button class="btn primary">Salvar cliente</button></div></form></section><section class="panel"><form class="search"><input name="q" placeholder="Buscar cliente..." value="<?=e($q)?>"><button class="btn">Buscar</button></form><div class="table-wrap"><table><thead><tr><th>Nome</th><th>Documento</th><th>Contato</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><small><?=e($r['email'])?></small></td><td><?=e($r['document'])?></td><td><?=e($r['phone'])?></td><td><a href="index.php?page=customers&edit=<?=$r['id']?>">Editar</a></td></tr><?php endforeach;?></tbody></table></div></section></div><?php require __DIR__.'/../../includes/footer.php';?>
